    if("LIFECYCLE".equals(kind)){JSONObject e=object(payload);if("OPENED".equals(e.getString("kind"))){for(String key:Arrays.asList("run","epoch","boot","generation","operator","profileId"))if(!link.getString(key).equals(e.getString(key)))throw new IOException("REVIEW_OPENED_CONTEXT");if(!link.getString("APSHA256").equals(e.getString("binarySHA256")))throw new IOException("REVIEW_OPENED_AP");opened=true;}}
