    if("TX_WRITTEN".equals(kind)){if(!Values.hash(payload).equals(lastIntent))throw new IOException("REVIEW_WRITE_WITHOUT_INTENT");lastIntent=null;new Mavlink().receive(payload,(id,sys,comp,s,p)->{if(sys==255&&comp==190&&(id==70||id==76&&(Mavlink.u16(p,28)==400||Mavlink.u16(p,28)==22||Mavlink.u16(p,28)==176&&Mavlink.f32(p,4)!=9f))){ground.landWritten=false;ground.groups=0;}if(id==76&&sys==255&&comp==190&&Mavlink.u16(p,28)==176&&Mavlink.f32(p,4)==9f&&validLand(p)&&ground.userLand){ground.landWritten=true;ground.usedHb=ground.hbN;ground.usedLand=ground.landN;ground.usedPos=ground.posN;ground.groups=0;}});}
